input.command:
duckdb -c "
LOAD spatial; LOAD httpfs;
SET geometry_always_xy = true;
SELECT tier, entity_kind, basis, geom_method, count(*) n, 
       min(weight) minw, max(weight) maxw, avg(weight) avgw,
       ST_GeometryType(any_value(geometry)) gt
FROM read_parquet('https://data.source.coop/tristangruppwri/soft-commodity-infrastructure/facilities/BR_facilities.parquet')
GROUP BY tier, entity_kind, basis, geom_method
ORDER BY tier;
" 2>&1 | tail -60

