time duckdb analysis.duckdb -c "
LOAD spatial; LOAD httpfs;
SET geometry_always_xy = true;

CREATE OR REPLACE TABLE field_parcel_intersect AS
SELECT f.Id AS field_id, p.cod_imovel,
       ST_Area(ST_Intersection(f.geometry, p.geom)) AS inter_area,
       ST_Area(f.geometry) AS field_area
FROM fields_env f
JOIN listed_parcels p
  ON ST_Intersects(f.geometry, p.geom);

SELECT count(*) FROM field_parcel_intersect;
"

duckdb analysis.duckdb -c "
LOAD spatial; LOAD httpfs;
SET geometry_always_xy = true;

CREATE OR REPLACE TABLE field_single AS
SELECT field_id, cod_imovel, inter_area / field_area AS frac
FROM field_parcel_intersect
WHERE inter_area > 0;

SELECT count(*) FROM field_single;
SELECT count(DISTINCT field_id) FROM field_single;
"

time duckdb analysis.duckdb -c "
LOAD spatial; LOAD httpfs;
SET geometry_always_xy = true;

CREATE OR REPLACE TABLE field_union_frac AS
SELECT f.Id AS field_id,
       CASE WHEN ST_Intersects(f.geometry, b.geom)
            THEN ST_Area(ST_Intersection(f.geometry, b.geom)) / ST_Area(f.geometry)
            ELSE 0 END AS union_frac
FROM fields_env f, buffered_union b;

SELECT count(*), sum(CASE WHEN union_frac > 0 THEN 1 ELSE 0 END) FROM field_union_frac;
"

duckdb analysis.duckdb -c "
LOAD spatial; LOAD httpfs;
SET geometry_always_xy = true;

CREATE OR REPLACE TABLE field_single_ranked AS
SELECT *,
  max(frac) OVER (PARTITION BY field_id) AS max_frac
FROM field_single;

CREATE OR REPLACE TABLE field_primary AS
SELECT field_id, cod_imovel AS primary_cod_imovel, max_frac AS max_single_frac
FROM (
  SELECT *, row_number() OVER (PARTITION BY field_id ORDER BY cod_imovel ASC) AS rn
  FROM field_single_ranked
  WHERE frac >= max_frac - 1e-9
)
WHERE rn = 1;

SELECT count(*) FROM field_primary;
"

